contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking arbitrary inputs
    function run(address[] calldata _tos, uint[] calldata v) public payable {
        // No precondition on inputs besides what we will observe; caller of c.transfer must be this contract
        // Read observable state before the call
        address before_from = c.from();
        address before_caddress = c.caddress();

        bool reverted;
        bool ret;
        // call transfer and capture whether it reverted and its return value
        try c.transfer(_tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // General rule asserted:
        // If the call did not revert then it must have returned true, and the public state variables remain unchanged.
        // Additionally, the call can only succeed when the contract's required conditions hold from its public view:
        // namely that msg.sender inside C was the hardcoded address (enforced in C) and that _tos.length>0.
        // We express that by requiring: if not reverted then ret==true and c.from and c.caddress unchanged and _tos.length>0.
        assert(reverted || (ret == true && c.from() == before_from && c.caddress() == before_caddress && _tos.length > 0));
    }

    receive() external payable {}
}

